Here is the commit message:
drm/amdgpu: return -EFAULT if copy_to_user() fails

If copy_to_user() fails then this should return -EFAULT instead of
-EINVAL.

Fixes: c65b0805e77919 ("drm/amdgpu: RAS EEPROM table is now in debugfs")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Reviewed-by: Luben Tuikov <luben.tuikov@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>

Here is the root cause:
The bug arises from the incorrect error code being returned when the `copy_to_user()` function fails. Instead of returning `-EFAULT`, which indicates a bad address or memory access issue, the code was incorrectly returning `-EINVAL`, which signifies an invalid argument. This misrepresentation of the error type could lead to confusion and improper handling of the error in the calling functions.

Here is the patch:

 static ssize_t
 amdgpu_ras_debugfs_eeprom_size_read(struct file *f, char __user *buf,
 				    size_t size, loff_t *pos)
 {
 	struct amdgpu_device *adev = (struct amdgpu_device *)file_inode(f)->i_private;
 	struct amdgpu_ras *ras = amdgpu_ras_get_context(adev);
 	struct amdgpu_ras_eeprom_control *control = ras ? &ras->eeprom_control : NULL;
 	u8 data[50];
 	int res;

 	if (!size)
 		return size;

 	if (!ras || !control) {
 		res = snprintf(data, sizeof(data), "Not supported\n");
 	} else {
 		res = snprintf(data, sizeof(data), "%d bytes or %d records\n",
 			       RAS_TBL_SIZE_BYTES, control->ras_max_record_count);
 	}

 	if (*pos >= res)
 		return 0;

 	res -= *pos;
 	res = min_t(size_t, res, size);

 	if (copy_to_user(buf, &data[*pos], res))
-		return -EINVAL;
+		return -EFAULT;

 	*pos += res;

 	return res;
 }


 static ssize_t
 amdgpu_ras_debugfs_eeprom_table_read(struct file *f, char __user *buf,
 				     size_t size, loff_t *pos)
 {
 	struct amdgpu_device *adev = (struct amdgpu_device *)file_inode(f)->i_private;
 	struct amdgpu_ras *ras = amdgpu_ras_get_context(adev);
 	struct amdgpu_ras_eeprom_control *control = ras ? &ras->eeprom_control : NULL;
 	u8 data[81];
 	int res;

 	if (!size)
 		return size;

 	if (!ras || !control) {
 		res = snprintf(data, sizeof(data), "Not supported\n");
 		if (*pos >= res)
 			return 0;

 		res -= *pos;
 		res = min_t(size_t, res, size);

 		if (copy_to_user(buf, &data[*pos], res))
-			return -EINVAL;
+			return -EFAULT;

 		*pos += res;

 		return res;
 	} else {
 		return amdgpu_ras_debugfs_table_read(f, buf, size, pos);
 	}
 }



